mapper.select:
select a.id, a.advance_delivery_id, a.material_id, a.next_flag, a.plan_date, a.predict_date, a.predict_count, a.receive_count, a.detection_count, a.detection_fail_type, a.detection_fail_remark, a.registration_count, a.putaway_count, a.produced_date, a.batch_code, a.remark, a.create_by, a.create_time, b.code as advanceDeliveryCode, b.`type` as advanceDeliveryType, b.create_by as maker, m.code as materialCode, m.name as materialName, m.unit_price AS price, m.unit_id, m.specifications, tu.name as unitName ,(select count(*) from t_material_detail md where md.del_flag = '0' and md.advance_registration_id = a.id and md.rfid_head is not null) as returnCount from t_advance_delivery_detail a left join t_advance_delivery b on a.advance_delivery_id = b.id left join t_material m on a.material_id = m.id left join t_unit tu on m.unit_id = tu.id
inner join sys_user u on u.user_name = a.create_by and u.status = '0' inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'
a.del_flag = '0' and a.detection_count > 0 and a.advance_delivery_id = #{advanceDeliveryId}
and a.material_id = #{materialId} and a.next_flag = #{nextFlag} and a.plan_date = #{planDate} and a.predict_date = #{predictDate} and a.predict_count = #{predictCount} and a.receive_count = #{receiveCount} and a.detection_count = #{detectionCount} and a.detection_fail_type = #{detectionFailType}
and a.detection_fail_remark = #{detectionFailRemark}
and a.registration_count = #{registrationCount}
and a.produced_date = #{producedDate} and a.batch_code like concat('%', #{batchCode}, '%')
and b.code like concat('%', #{advanceDeliveryCode}, '%')
and b.`type` = #{advanceDeliveryType}
and b.delivery_module = #{deliveryModule}
#{status}
and m.code like concat('%',#{materialCode},'%')
and m.name like concat('%',#{materialName},'%')
${params.dataScope} order by a.create_time desc

select a.id, a.advance_delivery_id, a.material_id, a.next_flag, a.plan_date, a.predict_count, a.receive_count, a.detection_count, a.registration_count, a.putaway_count, a.produced_date, a.batch_code, a.create_by, a.create_time, b.code as advanceDeliveryCode, m.code as materialCode, m.name as materialName, m.unit_price AS price, m.unit_id, m.specifications, tu.name as unitName, ifnull(sum(md.rfid_count),0) as returnCount from t_advance_delivery_detail a left join t_advance_delivery b on a.advance_delivery_id = b.id left join t_material m on a.material_id = m.id left join t_unit tu on m.unit_id = tu.id left join t_material_detail md on md.advance_registration_id = a.id and md.rfid_head is not null and md.del_flag = '0'
inner join sys_user u on u.user_name = a.create_by and u.status = '0' inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'
a.del_flag = '0' and b.status not in ('1','8','9') and b.delivery_module = '0' and a.next_flag in ( '0' , '1','3') and a.advance_delivery_id = #{advanceDeliveryId}
and a.material_id = #{materialId} and a.next_flag = #{nextFlag} and a.plan_date = #{planDate} and a.predict_date = #{predictDate} and a.predict_count = #{predictCount} and a.receive_count = #{receiveCount} and a.detection_count = #{detectionCount} and a.detection_fail_type = #{detectionFailType}
and a.detection_fail_remark = #{detectionFailRemark}
and a.registration_count = #{registrationCount}
and a.produced_date = #{producedDate} and a.batch_code like concat('%', #{batchCode}, '%')
and b.code like concat('%', #{advanceDeliveryCode}, '%')
and b.`type` = #{advanceDeliveryType}
and m.code like concat ('%',#{materialCode}, '%')
and m.name like concat ('%',#{materialName}, '%')
and b.delivery_module = #{deliveryModule}
${params.dataScope} group by a.id having a.predict_count > returnCount order by a.create_time desc
